/* Concept explanations. Every concept has the core fields (l1, l2, take, aid, hr, mistake).
   Priority concepts (Modules 1–5 essentials and the three sample journeys) have the full record.
   Source tags on explanations: course concept tag from course.js; l3/l4 and allied notes are
   marked separately in the page where they go beyond the course. */
window.GMB = window.GMB || {};

GMB.DETAIL = {
"C01.1": { l1: "AI is the broad goal of machines doing tasks that need intelligence. Machine learning (ML) is AI that learns patterns from data. Deep learning (DL) is ML using large neural networks. Generative AI (GenAI) is deep learning that creates new text, images or code.",
  l2: "Most HR tech you buy is predictive ML (scores, rankings, attrition risk). GenAI tools draft, summarise and converse. Knowing which one a vendor sells tells you what evidence to ask for: accuracy metrics for predictive tools, output-review processes for generative ones.",
  take: "AI ⊃ ML ⊃ DL ⊃ GenAI. Predictive models classify or forecast; generative models create new content.", aid: "Nested boxes: AI holds ML, ML holds DL, DL holds GenAI.",
  hr: "An attrition-risk score is predictive ML. A tool that writes the stay-interview guide is GenAI.", mistake: "Calling every analytics feature 'GenAI' and evaluating it the wrong way." },
"C01.2": { l1: "AI is worth it when the time or quality it gains is more than what it costs to set up and check.",
  l2: "Estimate hours saved per week × loaded hourly cost × weeks, plus quality and speed gains, minus tool cost, setup time and the time humans spend reviewing outputs. Review time is the cost people forget.",
  take: "ROI = (time saved + quality/speed value − tool, setup and review cost) ÷ cost.", aid: "Count the review minutes, not just the saved minutes.",
  hr: "Twelve recruiters each saving 3 hours/week on interview summaries ≈ 36 hours/week, less 6 hours of spot-checking.", mistake: "Claiming 'saves 80% of time' without measuring a baseline." },
"C01.3": { l1: "Before using AI, list your recurring tasks and decide for each: should AI do it (Automate), help me do it faster (Accelerate), help me think better (Augment), or stay away (Avoid AI)?",
  l2: "The four-bucket sort turns 'we should use AI' into a prioritised list. Rank the Automate and Accelerate candidates by impact × feasibility. Avoid-AI items protect you from reputational and legal risk — they are a result, not a failure.",
  l3: "Inputs: a task inventory with frequency, time per task, rules vs judgement, data sensitivity, error cost. Automate = rule-heavy, high-frequency, low judgement. Accelerate = human owns output, AI drafts. Augment = AI widens thinking (options, critiques). Avoid = high-stakes judgement, sensitive data, or legal accountability. Prioritise with impact × feasibility.",
  l4: "Buckets shift with controls: final hiring decisions are Avoid for automation, but Augment once a structured rubric and human decision-maker exist. Trade-off: aggressive Automate choices deliver ROI fast but raise oversight cost; Augment is slower to show ROI but safer for judgement work.",
  why: "Most failed AI pilots chose the wrong task, not the wrong tool.", how: "List tasks → score frequency, effort, judgement, sensitivity → assign a bucket → rank by impact × feasibility → pick 1–2 pilots.",
  biz: "This is the opening move of any AI consulting engagement: a task-level opportunity map.", analogy: "Sorting a cupboard into keep, donate, repair and bin before buying new storage.",
  ex: "A TA team lists 25 tasks; interview scheduling goes to Automate, JD drafting to Accelerate, workforce-plan scenarios to Augment, final selection to Avoid AI.",
  hr: "Interview-feedback summaries = Accelerate; reminder emails = Automate; offer-negotiation strategy = Augment; rejecting candidates without review = Avoid AI.",
  gen: "Finance: invoice matching = Automate; variance commentary = Accelerate; scenario planning = Augment; final audit sign-off = Avoid AI.",
  mistakes: ["Starting from a tool instead of a task", "Treating 'Avoid AI' as an empty category", "Ignoring review cost when ranking"],
  risks: ["Over-automating judgement work", "Estimates of time saved that were never measured"],
  confused: [["C05.1", "C01.3 decides whether AI should be involved at all; C05.1 scores whether a process is suitable for automation."]],
  tools: ["Spreadsheet task inventory", "Any chat assistant to brainstorm tasks"], notWhen: ["A single obvious task where the choice is already made"],
  exercise: "List ten tasks from your last two weeks. Put each into one of the four buckets and write a one-line reason. Then pick the top two by impact × feasibility.",
  predict: { q: "Where does 'deciding which of three finalists gets the offer' belong, and why?", a: "Avoid AI for the decision itself (high stakes, accountability, bias risk). AI can Augment by summarising evidence against the rubric for the decision-maker." },
  allied: [{ t: "Impact × feasibility matrix", s: "A standard prioritisation grid used in consulting; plots value against ease of delivery.", src: "INF" }] },
"C01.4": { l1: "AI is very good at producing fluent language and spotting patterns. It does not check facts by itself, doesn't know your private data, and can't take responsibility for a decision.",
  l2: "Use AI for drafting, summarising, classifying and suggesting. Don't rely on it for facts it wasn't given, live numbers, or accountable judgements without review.",
  take: "AI generates plausible output from patterns; it does not verify truth or own decisions.", aid: "Fluent is not the same as factual.",
  hr: "Good: draft interview questions from a JD. Not good: 'What is our current offer-acceptance rate?' with no data connected.", mistake: "Asking an unconnected chatbot about live internal numbers." },
"C01.5": { l1: "Accuracy means the answer is right. Reliability means it is right consistently. Trust is earned when both are proven and someone checks the important outputs.",
  l2: "Set a risk level for each use case. Low risk (internal drafts) needs light checks. High risk (anything affecting candidates' outcomes or legal commitments) needs human review, logging and clear accountability.",
  l3: "Risk = impact on people × likelihood of error × reversibility × exposure (internal vs external) × regulatory sensitivity. Oversight scales with risk: sampling for low, approval gates for medium, mandatory human decision for high.",
  l4: "Accuracy on a test set doesn't guarantee reliability in production (drift, unusual inputs). Over-reviewing low-risk work kills ROI; under-reviewing high-risk work creates incidents. Design the oversight cost into the business case.",
  why: "This is the bridge between 'AI works in a demo' and 'AI is safe to use at work'.", how: "Classify risk → choose oversight level → define who checks what → measure accuracy and consistency → review regularly.",
  biz: "Leaders adopt AI when they can see the controls, not just the capability.", analogy: "A new hire: accurate on day one, trusted once they've been consistently right and supervised for a while.",
  ex: "An AI drafting internal meeting notes: low risk, spot-check weekly. An AI drafting rejection emails: medium-high, recruiter approves each.",
  hr: "AI-ranked shortlists affect candidates' livelihoods: high risk, human decision required, bias monitoring needed.",
  gen: "Customer-service replies about refunds: medium risk, approval for amounts above a threshold.",
  mistakes: ["Treating one good demo as proof of reliability", "Same oversight for every use case"],
  risks: ["Automation bias: reviewers rubber-stamp AI output", "Silent drift when inputs change"],
  confused: [["C14.4", "C01.5 decides how much oversight a use case needs; C14.4 designs the review step itself."]],
  tools: ["Risk register", "Evaluation set"], notWhen: [],
  exercise: "Rate three of your AI ideas Low / Medium / High risk using impact, reversibility and exposure. Write the oversight rule for each.",
  predict: { q: "An assistant answers 95 of 100 test questions correctly. Is it reliable enough for candidate-facing use?", a: "Not yet. Check which 5 failed and their impact, test consistency on repeated and unusual inputs, and add a human or 'not found' fallback for candidate-facing answers." },
  allied: [{ t: "NIST AI RMF: Govern, Map, Measure, Manage", s: "A widely used framework for organising AI risk work. Extends C01.5 by giving a structure for oversight.", src: "EXT" }] },
"C02.1": { l1: "An LLM writes one small piece of text (a token) at a time, each time picking a likely next piece based on everything before it.",
  l2: "Because it predicts likely text, wording and context strongly change the output. Give it the right context and it predicts the right kind of answer; leave gaps and it fills them with plausible guesses.",
  take: "LLMs generate text token by token by predicting the most likely continuation given the context.", aid: "It predicts the next word, it doesn't look anything up.",
  hr: "'Write a JD' gives a generic JD; adding role level, location, team and must-haves changes every predicted word.", mistake: "Assuming the model 'knows' your company because it sounds confident." },
"C02.2": { l1: "A model is first trained on huge amounts of public text, then tuned to follow instructions. It can only use what it learned plus what you put in the conversation.",
  l2: "Pre-training gives general knowledge up to a cut-off date. Instruction tuning makes it helpful. The context window limits how much it can read at once. Some models also handle images and audio.",
  take: "Knowledge = training data (to a cut-off) + what's in the context window.", aid: "Trained memory plus the page in front of it.",
  hr: "It won't know a labour-law change from last month unless you provide the text.", mistake: "Expecting a model to know recent or private information." },
"C02.3": { l1: "AI sometimes makes things up because it is built to produce text that sounds right, not text that is checked.",
  l2: "Hallucinations rise when the model lacks the facts (private or recent information), when the prompt is vague, or when it is pushed to answer anyway. The fixes are grounding in sources, permission to say 'I don't know', and verification.",
  l3: "Causes: missing knowledge, ambiguous instructions, pressure to be complete, long or conflicting context, and sampling randomness. Controls: retrieval with citations (C11.4), explicit 'not found' rules, structured outputs that separate facts from inferences, lower temperature for factual tasks, human review for high-stakes claims.",
  l4: "Hallucination can be reduced, not eliminated. Grounding moves the risk from 'made up' to 'misread or mis-retrieved', which is easier to detect with citations. Trade-off: strict 'answer only from sources' rules reduce helpfulness on edge questions.",
  why: "It is the single most common reason AI outputs can't be used unchecked.", how: "Model predicts plausible text → no fact source → gap filled with plausible invention.",
  biz: "Every executive deck or policy answer produced with AI needs a claims check (C06.3).", analogy: "A confident new joiner who would rather guess than say 'let me check'.",
  ex: "Asked for 'recent studies on AI in hiring', a model lists papers with plausible titles that don't exist.",
  hr: "A recruiter assistant states a notice-period buy-out rule that isn't in your policy.",
  gen: "A sales assistant quotes a discount tier the company never offered.",
  mistakes: ["Adding 'be accurate' and expecting facts to appear", "Trusting citations without opening them"],
  risks: ["Fabricated policy statements given to candidates", "Invented numbers in leadership decks"],
  confused: [["C02.6", "C02.3 explains why errors happen; C02.6 is the practical repair routine."]],
  tools: ["RAG tools", "NotebookLM", "Citation checks"], notWhen: [],
  exercise: "Ask a chatbot about a specific internal policy it cannot know. Note what it invents. Then provide the policy text and ask again with 'answer only from the text; say not found if absent'. Compare.",
  predict: { q: "Will raising the temperature make answers about your leave policy more accurate?", a: "No. Higher temperature increases variety, and so the chance of invented details. Accuracy needs the policy as a source." },
  allied: [{ t: "Grounding and faithfulness evaluation", s: "Measuring whether each claim is supported by the provided sources. Extends C02.3 into a testable metric.", src: "ALLIED" }] },
"C02.4": { l1: "Different AI models are better at different things, and they cost different amounts. Compare them on what matters to your task.",
  l2: "Business criteria: output quality on your task, speed, cost per use, how much text it can read, where your data goes, and whether it handles files or images.",
  take: "Choose models on task quality, speed, cost, context length, data privacy and modality — tested on your own examples.", aid: "Test on your work, not on benchmarks.",
  hr: "A fast, cheap model for tagging 5,000 CVs by skill; a stronger model for drafting the TA strategy paper.", mistake: "Picking the 'best' model for everything regardless of cost or privacy." },
"C02.5": { l1: "Pick the AI that fits the job, set it up so it behaves predictably, and be able to explain why you chose it.",
  l2: "A justification names the task, the criteria, the options tested, the result and the controls. Leaders and auditors ask 'why this tool?' — have the answer written.",
  take: "Choose by fit, control through instructions and settings, justify with tested evidence.", aid: "Fit, control, justify.",
  hr: "'We chose an enterprise assistant over a consumer chatbot because candidate data must stay within our tenant.'", mistake: "Justifying a choice by popularity." },
"C02.6": { l1: "When AI gives an incomplete or wrong answer, fix the cause: give more context, split the task, ask for a set format, or give it the source.",
  l2: "Diagnose first: missing facts → provide or ground; task too big → split into steps; format wrong → specify structure; drifting → add constraints and examples; still unsure → verify.",
  take: "Diagnose the cause, then apply the matching fix: context, decomposition, format, grounding or verification.", aid: "Diagnose before you re-prompt.",
  hr: "Feedback summary misses competencies → supply the competency framework and require one line per competency.", mistake: "Re-running the same prompt hoping for a better answer." },
"C03.1": { l1: "Zero-shot: just ask. Few-shot: show a few examples first. Role-based: tell the AI who to act as.",
  l2: "Zero-shot is fine for simple, common tasks. Few-shot helps when you need a specific format or judgement style. A role sets vocabulary and perspective but doesn't replace clear instructions.",
  take: "Zero-shot = instruction only; few-shot = instruction + examples; role-based = assigns a persona to shape perspective.", aid: "Ask, show, or cast.",
  hr: "Few-shot: give two well-written rejection notes so the AI matches your tone.", mistake: "Thinking 'You are an expert recruiter' alone makes the output expert." },
"C03.2": { l1: "A prompt is a work brief. COSTAR is a checklist so the brief isn't missing anything: Context, Objective, Style, Tone, Audience, Response format.",
  l2: "Most weak AI output comes from a weak brief. COSTAR forces the six decisions a good manager makes before delegating. It is most valuable for repeated, audience-facing outputs: emails, summaries, briefs.",
  l3: "In an automation (C05.2) the COSTAR prompt becomes the AI Step template: Context is filled from data fields; Response specifies a structure the next step can parse (C03.5). Constraints and examples (C03.3) are added on top, because COSTAR doesn't state what the model must not do.",
  l4: "COSTAR is a completeness checklist, not a guarantee of accuracy. Its gaps: no explicit constraints, no grounding source, no examples, no failure rule ('if data is missing, say so'). Experts extend it with constraints, examples, grounding and a failure rule. Public origin: GovTech Singapore's 2023 prompt-engineering competition write-up.",
  why: "It gives you a repeatable way to brief AI so outputs are usable first time more often.", how: "Fill each of the six slots explicitly, then add constraints and examples.",
  biz: "Standard prompt templates across a team reduce variation in quality.", analogy: "Briefing an agency: who we are, what we need, how it should read and sound, who reads it, what to deliver.",
  ex: "Campus-drive invitation to a Training & Placement Officer with college, roles, dates, tone and a 150-word limit.",
  hr: "C: we hire 40 graduate engineers in Pune; O: invite the TPO to schedule a drive; S: concise business email; T: warm and respectful; A: TPO of a tier-2 college; R: subject line + 120–150 words + three proposed dates.",
  gen: "Board update on supply-chain delays: context of delays, objective to secure decision, formal style, calm tone, board audience, one-page format.",
  mistakes: ["One-line Context", "Audience left out", "Response = 'be detailed'"],
  risks: ["A complete-looking prompt can still produce invented facts if no source is given"],
  confused: [["C03.3", "COSTAR frames the request; the four building blocks add constraints and examples."]],
  tools: ["Any chat assistant", "Prompt playgrounds", "Automation AI steps"], notWhen: ["Open brainstorming where you want breadth, not a fixed format"],
  exercise: "Write a COSTAR prompt for an interview-invitation email for a senior data engineer. Then score it in the Prompt Lab.",
  predict: { q: "Which COSTAR elements are missing from: 'Write a LinkedIn post about our graduate programme, make it engaging'?", a: "Context (which programme, which company), Audience (students, parents, faculty?), Response (length, hashtags, call to action). 'Engaging' is a vague Tone; Style is unstated." },
  allied: [{ t: "Context engineering", s: "Choosing everything that goes into the model's context: instructions, documents, memory, tool results. Extends COSTAR's Context slot into the bridge to RAG and agents.", src: "ALLIED" }, { t: "Prompt injection", s: "Text inside inputs (for example a CV) can try to override your instructions. OWASP lists it as the top LLM risk.", src: "EXT" }],
  cvp: "The course teaches COSTAR as the core structure. Current practice adds explicit constraints, examples, grounding and a failure rule. Use COSTAR wording in the exam; use COSTAR plus the extras at work." },
"C03.3": { l1: "A good prompt has four parts: the background (context), what to do (instructions), the limits (constraints), and samples of good output (examples).",
  l2: "When output is weak, check which block is missing. Missing context → generic output. Unclear instruction → wrong task. No constraints → too long, off-policy or invented. No examples → wrong format or tone.",
  l3: "Order matters: context first, then instructions, constraints and examples, with the input data clearly delimited (for example inside tags or quotes) so the model doesn't confuse data with instructions. Delimiting also reduces prompt-injection risk.",
  l4: "More context isn't always better: irrelevant context dilutes attention and costs tokens. Examples can over-constrain (the model copies them too closely). Balance with 2–3 varied examples.",
  why: "It turns prompt fixing from guesswork into diagnosis.", how: "Context → Instructions → Constraints → Examples → delimited input.",
  biz: "A diagnostic vocabulary teams can use to review each other's prompts.", analogy: "A recipe: background on the dish, the steps, what not to do, and a photo of the result.",
  ex: "A summariser that ignores length limits is missing a constraint.",
  hr: "Interview-kit prompt: context (role, level, competencies), instruction (8 behavioural questions), constraints (no questions on age, family or religion), example (one model question with a scoring guide).",
  gen: "Sales-email prompt: product context, instruction, constraint (no pricing promises), one example email.",
  mistakes: ["Putting constraints in the middle of a long context", "Mixing instructions with pasted data"],
  risks: ["Unclear separation lets instructions hidden in data take over"],
  confused: [["C03.2", "COSTAR is a framing checklist; the four blocks are a diagnostic for what's missing."]],
  tools: ["Any LLM"], notWhen: [],
  exercise: "Take a prompt you used this week. Label each sentence C, I, Cn or E. Which block is missing? Add it and compare outputs.",
  predict: { q: "A prompt produces the right content but 800 words instead of 200. Which block is missing?", a: "Constraints (length limit), and possibly the Response specification." } },
"C03.4": { l1: "Anchors are reference points you give the AI (a template, a past example, a definition). Iterative refinement means testing, looking at the result and improving the prompt step by step.",
  l2: "Keep a short log: version, change, result. Stress-test with unclear or tricky inputs to find where the prompt breaks before users do.",
  take: "Anchor the output with references, then refine through test → observe → revise, including ambiguous test inputs.", aid: "Anchor it, test it, tune it.",
  hr: "Anchor a JD prompt to your house JD template; stress-test with a vague hiring-manager brief.", mistake: "Changing several things at once so you don't know what helped." },
"C03.5": { l1: "Ask the AI to answer in a fixed shape (a table, set headings, or a list of fields) so people and other tools can use it easily.",
  l2: "Structured outputs make AI results consistent and machine-readable. They are what lets an AI step feed the next step of an automation (C05.2) or an agent handoff (C13.4).",
  l3: "Specify field names, types and allowed values; for JSON give a schema or an example object; include a field for 'unknown' or 'not found'. Many model APIs can enforce a JSON schema (structured output mode).",
  l4: "Rigid schemas reduce creativity and can force the model to fill fields it has no evidence for — always allow null or unknown. Validate outputs before the next step uses them.",
  why: "Unstructured text is the most common reason AI steps break automations.", how: "Define fields → give example → require unknown values to be marked → validate.",
  biz: "Turns AI from a writing aid into a component of business processes.", analogy: "A form instead of a free-text letter.",
  ex: "Meeting notes returned as {decisions[], actions[{owner, due}], risks[]}.",
  hr: "Interview feedback converted into {candidate_id, competency_scores{}, evidence[], recommendation: hire|no_hire|unsure} for the ATS.",
  gen: "Support tickets classified into {category, urgency, product, summary}.",
  mistakes: ["No 'unknown' option", "Field names that change between runs"],
  risks: ["Model invents values to complete required fields"],
  confused: [["C03.6", "Structured outputs fix the shape; generation controls tune randomness and length."]],
  tools: ["JSON mode / structured outputs", "n8n output parser", "Sheets"], notWhen: ["Exploratory writing where form would get in the way"],
  exercise: "Design a JSON output for summarising a candidate's interview loop. Include at least one field that must say 'unknown' when evidence is missing.",
  predict: { q: "Why must a structured output include an 'unknown' option?", a: "Without it the model is pushed to invent a value to fill every field, a source of hallucination." },
  allied: [{ t: "Function / tool calling", s: "Structured outputs are also how models call tools: they emit arguments in a schema. Extends C03.5 to agents.", src: "ALLIED" }] },
"C03.6": { l1: "Settings like temperature control how creative or predictable the AI is. Length and depth settings control how much it writes.",
  l2: "Low temperature for consistent, factual or format-bound tasks; higher for brainstorming. Set maximum length to control cost and verbosity.",
  take: "Temperature controls randomness: low for consistency, higher for variety.", aid: "Cold for facts, warm for ideas.",
  hr: "JD standardisation: low temperature. Employer-branding taglines: higher.", mistake: "Using high temperature for policy answers." },
"C03.7": { l1: "Don't paste personal or confidential information into AI tools that aren't approved for it. Rewrite prompts to remove names and sensitive details.",
  l2: "Replace names with roles or IDs, remove salary and health details, and use only approved enterprise tools for anything sensitive. Avoid wording that asks the AI to judge protected characteristics.",
  take: "Minimise and anonymise data in prompts; use approved tools; avoid risky phrasing.", aid: "Strip it before you ship it.",
  hr: "'Summarise Priya Sharma's interview; she's 42 and returning from maternity leave' → 'Summarise Candidate C-104's interview against the competency framework.'", mistake: "Pasting full CVs with contact details into a consumer chatbot." },
"C04.1": { l1: "AI tools come in families: chat assistants, writing tools, research tools, meeting note-takers, slide makers, automation platforms, analytics tools and assistant builders.",
  l2: "Map categories to your work before picking products. Many tasks are covered by one general assistant plus one automation tool.",
  take: "Categorise tools by job-to-be-done before comparing products.", aid: "Job first, tool second.", hr: "Meeting note-taker for intake calls; slide maker for QBRs; automation tool for reminders.", mistake: "Buying a tool for each task." },
"C04.2": { l1: "Choose tools by four questions: Is it valuable? Is it simple? What does it cost? Is it safe for our data?",
  l2: "Score each candidate tool on value, simplicity, cost and safety for a specific use case. Safety can veto: a great tool that sends candidate data to an unapproved service is out.",
  take: "Select tools on value – simplicity – cost – safety, for a specific use case.", aid: "VSCS: value, simplicity, cost, safety.", hr: "Three note-takers scored for intake calls; one fails safety because recordings are stored outside the region.", mistake: "Choosing on features alone." },
"C04.3": { l1: "Integrations are how tools pass information to each other automatically, through ready-made connectors, APIs or webhooks.",
  l2: "A connector is a pre-built link; an API is the door a system offers to other software; a webhook is a message one system sends when something happens.",
  take: "Connectors, APIs and webhooks let tools exchange data without copy-paste.", aid: "A webhook rings the bell; an API answers the door.", hr: "ATS sends a webhook when a candidate reaches 'Offer'; the automation reads details via the ATS API.", mistake: "Assuming every tool can connect to every other." },
"C04.4": { l1: "Map which tool you use at each step of your week, so tools support real work instead of piling up.", l2: "Draw your weekly workflow, mark the friction points, then place one tool per step.", take: "Map tools onto workflow steps; avoid tool sprawl.", aid: "One step, one tool.", hr: "Monday pipeline review: dashboard + AI summary; Tuesday intake calls: note-taker.", mistake: "Adding tools without retiring old ones." },
"C04.5": { l1: "New AI tools appear weekly. Set a routine to review a few, rather than chasing every launch.", l2: "Quarterly review, small pilots with success criteria, and a list of approved tools.", take: "Stay updated through a fixed evaluation cadence and small, measured pilots.", aid: "Review on a rhythm, not on a whim.", hr: "Quarterly 'tool clinic' for the TA team with a two-week pilot rule.", mistake: "Rolling out a tool after one demo." },
"C05.1": { l1: "Not every process should be automated. Good candidates happen often, follow clear rules, waste time, and don't need much human judgement.",
  l2: "Score a process on seven criteria: repetition, frequency, friction, impact, judgement required, data sensitivity and process stability. High judgement or high sensitivity means keep a human in the loop.",
  l3: "Score 0–3 each; judgement and sensitivity are reverse-scored. ≥ 14/21 is a good candidate. Unstable processes (changing every month) should be standardised before automating, or the automation will break.",
  l4: "Automating a broken process makes it fail faster. Partial automation (automate data gathering, keep the decision human) often beats full automation in ROI and risk.",
  why: "Picking the wrong process wastes the build effort and erodes trust in automation.", how: "Map the process → score seven criteria → decide full, partial or no automation.",
  biz: "The core diagnostic in a process-improvement consulting offer.", analogy: "Only put a dish on the conveyor belt if the recipe never changes.",
  ex: "Weekly pipeline report: high repetition, stable, low judgement → automate.", hr: "Interview reminders: automate fully. Shortlisting: partial (AI summarises, recruiter decides).", gen: "Finance: month-end accrual reminders → automate; accrual estimates → partial.",
  mistakes: ["Automating before standardising", "Ignoring data sensitivity"], risks: ["Brittle automations on unstable processes"],
  confused: [["C01.3", "C01.3 asks if AI belongs at all; C05.1 asks if the process suits automation."]],
  tools: ["Scoring sheet", "Process map"], notWhen: ["One-off tasks", "Processes under active redesign"],
  exercise: "Score candidate follow-up emails and offer approval on the seven criteria. Which is the better automation candidate and why?",
  predict: { q: "A process happens 200 times a week but the steps change every month. Automate now?", a: "Not yet. Stabilise and standardise the process first; low stability means frequent breakage." } },
"C05.2": { l1: "Every automation can be broken into six blocks: something starts it (Trigger), it gathers information (Data), it checks a rule (Decision), it connects to other tools (Integration), AI does a thinking step (AI Step), and it delivers a result (Output).",
  l2: "Describing a workflow in these six blocks makes hidden steps visible and shows exactly where AI adds value — and where it doesn't.",
  l3: "Trigger: event, schedule or manual. Data: fields and their source and freshness. Decision: rules or approvals. Integration: connectors/APIs/webhooks. AI Step: prompt template with structured output (C03.5). Output: message, record update or document. Governance (C05.4) wraps all six.",
  l4: "Put deterministic logic in Decision blocks, not in the AI Step; AI is for language and judgement-like tasks. Each block is a failure point: design what happens when data is missing or an integration fails.",
  why: "It is the course's core design language for automation.", how: "Write the six blocks for the current manual process, then mark which are automated.",
  biz: "A shared blueprint you can hand to a builder or a client.", analogy: "A relay race: each runner has a clear leg and hands the baton on.",
  ex: "New support email (Trigger) → extract sender and text (Data) → is it urgent? (Decision) → CRM lookup (Integration) → AI drafts reply (AI Step) → draft to agent queue (Output).",
  hr: "Candidate moves to 'Interview' in ATS (Trigger) → candidate and panel details (Data) → panel confirmed? (Decision) → calendar API (Integration) → AI drafts personalised invite (AI Step) → email after recruiter approval (Output).",
  gen: "Purchase order received → amounts and vendor → over threshold? → ERP → AI summarises exceptions → approver notified.",
  mistakes: ["Putting rules inside the AI prompt", "No owner for exceptions"], risks: ["Silent failures when an integration breaks"],
  confused: [["C13.1", "A workflow follows fixed blocks; an agent chooses its own next steps."]],
  tools: ["n8n", "Make", "Zapier", "Power Automate"], notWhen: ["Tasks needing open-ended reasoning paths (consider an agent)"],
  exercise: "Write the six blocks for your weekly hiring-manager status update.",
  predict: { q: "Should 'Is the candidate's notice period over 60 days?' be a Decision block or part of the AI Step?", a: "A Decision block. It is a deterministic rule; keep it out of the AI prompt." } },
"C05.3": { l1: "Real workflows need pauses for a person to approve, and alerts when something needs attention.", l2: "Add approval steps before high-impact actions (external emails, offers, data changes) and alerts for exceptions.", take: "Multi-step automations include branches, approvals and notifications.", aid: "Pause before it goes outside.", hr: "AI-drafted offer letter waits for HRBP approval before sending.", mistake: "Letting AI-generated messages go straight to candidates." },
"C05.4": { l1: "Governance means the automation is safe to run: someone approves risky steps, everything is logged, problems are escalated, and errors are handled.",
  l2: "Every workflow needs: approvals, logs, escalation rules, exception handling, tests and a handover owner.", take: "Workflow governance = approvals, logging, escalation, exception handling, testing and handover.", aid: "Approve, log, escalate, handle, test, hand over.",
  hr: "If the ATS API fails, the recruiter is alerted and the reminder is queued, not lost.", mistake: "No owner after the builder moves on." },
"C05.5": { l1: "The same automation patterns work in every function.", l2: "A TA reminder flow becomes a finance invoice-reminder flow with different data and approvers.", take: "Automation patterns transfer across HR, Ops, Sales, Product, Finance and Marketing.", aid: "Same blocks, different data.", hr: "Candidate follow-up → vendor follow-up.", mistake: "Rebuilding from scratch for each function." },
"C06.1": { l1: "One long document can be turned into many useful outputs: a summary, an FAQ, an SOP, an action list, a stakeholder update.", l2: "Write one prompt per asset with its own audience and format; keep the source as the single truth.", take: "Repurpose one source into multiple audience-specific assets.", aid: "One source, many shapes.", hr: "New referral policy → manager FAQ, employee post, recruiter SOP, leadership summary.", mistake: "One generic summary for every audience." },
"C06.2": { l1: "A business brief tells a story: the situation, the problem, and what we should do about it.", l2: "Plan the storyline (headline per slide) before generating slides. Audience-first: what decision should they make?", take: "Storyline architecture: structure the argument before generating content.", aid: "Headlines first, slides second.", hr: "TA quarterly review: situation (hiring targets), complication (offer declines up), resolution (comp review + faster offers).", mistake: "Generating slides before deciding the message." },
"C06.3": { l1: "Before AI-made content goes to leaders, check that every claim and number is true and traceable to a source.", l2: "List each claim, find its source, mark unsupported ones, and remove or verify them.", take: "Every claim in executive communication must trace to a verified source.", aid: "No source, no slide.", hr: "AI deck says 'industry offer-decline rate is 18%' — find the source or delete it.", mistake: "Trusting numbers because they look precise." },
"C06.4": { l1: "Decks can refresh automatically when the data changes.", l2: "Link data to a template; AI writes commentary from the new numbers; a human reviews before sharing.", take: "Auto-updating decks = data + template + AI commentary + human review.", aid: "Template once, refresh forever.", hr: "Monthly TA review deck refreshes from the hiring tracker.", mistake: "Auto-sending decks without review." },
"C07.1": { l1: "Dashboards are only as good as the data behind them. Clean, consistent tables make everything downstream work.",
  l2: "Seven rules: define the grain (what one row is), consistent data types, one date format, a flat table (no merged cells), a rule for missing values, clear column names, validation lists for categories.",
  take: "Dataset discipline: grain, types, dates, flat structure, missing values, naming, validation.", aid: "One row, one thing, one format.",
  hr: "Requisition tracker: one row per requisition, dates as YYYY-MM-DD, status from a dropdown, no merged header cells.", mistake: "Mixing requisition rows and candidate rows in one table." },
"C07.2": { l1: "Combine data from different places using a shared key, like a requisition ID.", l2: "Choose one source of truth per field; join on stable IDs; schedule refreshes.", take: "Connect sources with shared keys and a single source of truth.", aid: "Same key, same truth.", hr: "ATS export + offer tracker joined on requisition ID.", mistake: "Joining on names that are spelled differently." },
"C07.3": { l1: "Start from the goal, pick a number that shows progress (KPI), set the level that means 'act now' (threshold), decide what you'd do, and name who does it.",
  l2: "A KPI is only useful if crossing its threshold triggers a decision and an action. Every KPI needs a formula, an owner, a refresh frequency, a threshold, a decision trigger and an action. Metrics with no decision attached are vanity metrics.",
  l3: "Goal: 'fill critical roles faster'. KPI: median days from requisition approval to offer acceptance, critical roles only. Threshold: > 45 days. Decision: escalate sourcing strategy. Action: TA lead adds agency + referral push within 5 days. Owner: TA lead. Refresh: weekly.",
  l4: "Too many KPIs dilute attention; pair a speed KPI with a quality KPI to avoid gaming (fast hires that leave early). Thresholds should come from baselines, not guesses.",
  why: "It is what turns dashboards into decisions.", how: "Goal → KPI (formula) → Threshold → Decision → Action, plus owner and refresh.",
  biz: "Leaders fund dashboards that change decisions, not dashboards that report.", analogy: "A car's fuel warning light: a measure, a level, and an obvious action.",
  ex: "Customer churn > 3% monthly triggers a retention campaign owned by CX.",
  hr: "Offer-acceptance rate < 80% for two consecutive months → comp benchmarking review, owner: TA head.",
  gen: "Inventory days > 60 → reorder-policy review, owner: supply-chain manager.",
  mistakes: ["KPIs without owners", "Thresholds picked without a baseline", "Counting activity (posts, calls) instead of outcomes"],
  risks: ["Gaming a single KPI"], confused: [["C08.4", "C07.3 designs the decision rule in advance; C08.4 applies it to new insights."]],
  tools: ["Sheets", "Excel", "Looker Studio", "Power BI"], notWhen: [],
  exercise: "Turn 'improve candidate experience' into two KPIs with formula, owner, refresh, threshold, decision and action.",
  predict: { q: "Is 'number of LinkedIn posts per month' a good TA KPI?", a: "Usually a vanity metric: no clear decision attached. Better: applications per post from target segments, with a threshold that triggers a content change." } },
"C07.4": { l1: "KPI views show the important numbers at a glance and refresh automatically.", l2: "Add anomaly rules (for example, flag a week 30% above average) so the dashboard tells you what changed.", take: "Automated KPI views with refresh and anomaly flags.", aid: "Let the dashboard raise its hand.", hr: "Flag any requisition open more than 60 days.", mistake: "Manual copy-paste refreshes." },
"C08.1": { l1: "You can give dashboard data to AI and ask what it shows.", l2: "Export a clean summary table, give context and definitions, and ask for specific outputs. Strip personal data first.", take: "Connect dashboards to AI by passing clean, defined, minimal data.", aid: "Clean data in, clear insight out.", hr: "Weekly KPI table + definitions → AI insight summary.", mistake: "Pasting raw data with candidate names." },
"C08.2": { l1: "Look for patterns (what usually happens), trends (direction over time) and anomalies (unusual jumps).", l2: "Compare against a baseline; separate one-off spikes from sustained trends; check seasonality before raising alarms.", take: "Patterns, trends and anomalies are judged against a baseline and season.", aid: "Compared with what?", hr: "Campus offers dip every March: seasonal pattern, not an anomaly.", mistake: "Reacting to one week's spike." },
"C08.3": { l1: "AI can write the weekly summary for leaders from the numbers.", l2: "Use a fixed structure: what changed, why it matters, what to do. Human reviews before sending.", take: "Leadership summaries: what changed, why it matters, what to do.", aid: "Changed, matters, do.", hr: "Monday TA brief to the CHRO.", mistake: "Listing numbers without implications." },
"C08.4": { l1: "An insight is only useful if it leads to a decision and someone acts on it.", l2: "Attach a recommended action, an owner and a deadline to every insight.", take: "Every insight needs a decision, an owner and a next step.", aid: "Insight without an owner is trivia.", hr: "'Agency hires leave faster' → review agency mix, owner: TA ops, by quarter end.", mistake: "Insight reports with no actions." },
"C09.1": { l1: "Good intelligence starts with a question you need answered, then collects only the signals that help answer it.",
  l2: "The chain: strategic question → dimensions → signals → sources → credibility → validation → analysis → business relevance → decision supported → owner → action → update cadence.",
  take: "Intelligence work starts from a decision-linked question and ends in an owned action.", aid: "Question first, sources second, action last.",
  hr: "'Are competitors building GenAI teams in Bengaluru?' → signals: job postings, leadership hires; sources: careers pages, LinkedIn; cadence: weekly.", mistake: "Collecting news without a question." },
"C09.2": { l1: "Automatically gather and summarise signals about competitors and compare them over time.", l2: "Track the same items each week so changes stand out.", take: "Collect signals consistently to compare competitors and track change.", aid: "Same lens, every week.", hr: "Weekly count of competitors' open roles by function.", mistake: "Changing what you track every week." },
"C09.3": { l1: "Turn signals into alerts about trends, opportunities and risks, and into scorecards leaders can act on.", l2: "Use scorecards and opportunity maps; keep summaries decision-ready.", take: "Convert multi-source signals into trend, opportunity and risk alerts.", aid: "Signal → alert → decision.", hr: "Alert when a competitor raises campus offers above our band.", mistake: "Alerts nobody owns." },
"C09.4": { l1: "Intelligence isn't one report; it's a recurring watch.", l2: "Set a cadence, detect changes, alert on thresholds.", take: "Monitoring = cadence + change detection + thresholds.", aid: "Watch on a schedule.", hr: "Monthly skills-demand monitor for AI roles.", mistake: "One-off research treated as monitoring." },
"C10.1": { l1: "A smart assistant is set up for a specific job: who it serves, what it does and what it doesn't do.", l2: "Write a charter: purpose, role, users, scope (in and out), inputs. Narrow scope makes assistants reliable.", take: "Define purpose, role, users, scope and inputs before building an assistant.", aid: "Narrow scope, strong assistant.", hr: "Intake assistant: helps hiring managers write requisition briefs; does not discuss compensation.", mistake: "An assistant that 'helps with all of HR'." },
"C10.2": { l1: "Give the assistant the documents it needs (policies, SOPs, reports) so its answers reflect your organisation.", l2: "Choose a few relevant, current documents; more isn't better. For large collections, use RAG (C11).", take: "Inject relevant documents as context; keep them few, current and relevant.", aid: "The right three, not thirty.", hr: "Recruiter assistant gets the interview guide, competency framework and SLA document.", mistake: "Uploading every HR document." },
"C10.3": { l1: "Set how the assistant sounds and what it remembers.", l2: "Write a style guide; define what to remember (preferences) and what never to store (personal data).", take: "Tone, style and memory rules make assistants consistent and safe.", aid: "Remember preferences, never personal data.", hr: "Remembers a hiring manager's preferred format; never stores candidate details between sessions.", mistake: "Unlimited memory." },
"C10.4": { l1: "Guardrails stop the assistant doing things it shouldn't; conversation flow decides when it asks questions or hands over to a person.", l2: "Define refusals, clarifying questions, escalation triggers and hand-off.", take: "Guardrails + conversation flow = refusals, clarifying questions and escalation to a human.", aid: "Ask, refuse or escalate.", hr: "Candidate asks about salary → assistant gives the published range only and routes negotiation to the recruiter.", mistake: "No escalation path." },
"C10.5": { l1: "Test the assistant with planned questions before people use it, and keep improving it.", l2: "Build a test set (normal, edge, out-of-scope, adversarial), score with a rubric, log failures, fix, re-test.", take: "Evaluate assistants with a test set, rubric and failure log, continuously.", aid: "Test before trust.", hr: "Ten test prompts for the intake assistant, including one asking for a competitor's salaries.", mistake: "Launching after testing three happy-path questions." },
"C11.1": { l1: "Before answering, the AI looks up the right page in your documents — like an open-book exam.",
  l2: "A general model has never read your leave policy. Without retrieval it answers from general patterns and can be confidently wrong (C02.3). Retrieve-first thinking means: for any question about your organisation, first find the source, then answer from it.",
  l3: "Decide per use case: is the knowledge public and stable (prompt may do), private or changing (retrieve), or live transactional (integrate via API)? Retrieval is then designed: knowledge base, retrieval method, grounding instruction, citation and 'not found' rule.",
  l4: "Long-context models can read whole documents, reducing the need for retrieval on small sets, but cost more per query and don't solve permissions or freshness on large collections.",
  why: "Most business questions are about private, changing information the model has never seen.", how: "Question → find relevant source passages → answer only from them → cite.",
  biz: "Policy, SOP and product-knowledge assistants all rest on this idea.", analogy: "An open-book exam: look it up, then answer.",
  ex: "IT helpdesk assistant answers from current SOPs instead of generic advice.",
  hr: "Recruiter asks 'Can we pay a joining bonus for an L5 role in Pune?' → assistant retrieves Compensation Guidelines v3.2 §4 and answers with the citation, or says 'not covered — escalate to the Comp team'.",
  gen: "Sales asks about contract terms → assistant retrieves the current master service agreement clause.",
  mistakes: ["Uploading every document 'just in case'", "No 'not found' instruction, so the model fills gaps"],
  risks: ["Outdated documents produce confident, wrong answers"],
  confused: [["C10.2", "Context injection pastes chosen documents into every chat; RAG retrieves only the relevant passages per question."]],
  tools: ["Custom GPTs", "Claude Projects", "NotebookLM", "Flowise"], notWhen: ["Creative drafting with no factual source", "Live transactional data — use an integration"],
  exercise: "List five questions recruiters ask you weekly. For each, decide: prompt alone, retrieval, or live integration?",
  predict: { q: "'How many offers did we release this week?' Retrieval or integration?", a: "Integration: it is live transactional data from the ATS, not document knowledge." },
  allied: [{ t: "Long context vs RAG", s: "Larger context windows make 'just paste it' viable for small document sets; RAG remains the choice for large, permissioned or changing collections.", src: "ALLIED", vol: true }] },
"C11.2": { l1: "RAG has three steps: find the relevant text in your documents, add it to the question, and let the AI answer using that text.",
  l2: "RAG (retrieval-augmented generation) makes answers match your documents and lets you check them through citations. It is cheaper and more current than retraining a model.",
  l3: "Documents → prepare (clean, version, tag metadata) → split into chunks → index. Question → retrieve top-k relevant chunks → prompt = instructions + chunks + question → answer with citations → 'not found' if the chunks don't contain it. Failure points: wrong or outdated document; right document not retrieved; retrieved but misread; no 'not found' rule.",
  l4: "Chunk size: small = precise but loses context; large = more context but more noise. Vector, keyword or hybrid search. Reranking improves precision at a latency cost. Metadata filters (country, grade, effective date) prevent 'right policy, wrong country'.",
  why: "It is the standard architecture for trustworthy document-based assistants.", how: "Retrieve → augment the prompt → generate with citations.",
  biz: "Fast to deploy over existing documents; updates are a matter of updating documents, not models.", analogy: "A research assistant who pulls the right pages before you write.",
  ex: "Support bot over product manuals.", hr: "Policy assistant for recruiters over relocation, joining-bonus and referral rules.", gen: "Legal team assistant over contract templates.",
  mistakes: ["Blaming the model when retrieval failed", "No evaluation of retrieval separately from answers"],
  risks: ["Indirect prompt injection through documents", "Access leaks if retrieval ignores permissions"],
  confused: [["C11.1", "C11.1 is the decision to retrieve; C11.2 is the pipeline that does it."], ["fine-tuning", "Fine-tuning changes model behaviour; it is not a reliable way to add facts."]],
  tools: ["Flowise", "NotebookLM", "Custom GPTs", "Vector databases"], notWhen: ["A two-page document (paste it)", "Live data needs"],
  exercise: "Draw the RAG pipeline for an HR policy assistant and mark the four failure points with one test question each.",
  predict: { q: "The assistant cites the 2023 relocation policy for a 2025 question. Which stage failed?", a: "Knowledge-base governance: an outdated document is still indexed. It isn't a model failure." },
  allied: [{ t: "Embeddings & semantic search", s: "Text is turned into numeric vectors so passages with similar meaning are found even with different words. This is how most RAG retrieval works.", src: "ALLIED" }, { t: "Lewis et al., 2020", s: "The research paper that named retrieval-augmented generation.", src: "EXT" }] },
"C11.3": { l1: "Prepare documents before AI uses them: pick the right ones, clean them, label them and keep them current.", l2: "Select authoritative documents, remove duplicates and old versions, use clear headings, add metadata (owner, date, region, audience).", take: "Knowledge-base preparation: select, clean, structure, version and tag documents.", aid: "Garbage in, confident garbage out.", hr: "Five to ten HR policies, each with owner, version and effective date.", mistake: "Indexing drafts alongside final versions." },
"C11.4": { l1: "Make the AI show where each answer came from, and say 'not found' when the documents don't cover it.",
  l2: "Citation rules let users verify answers; a 'not found' rule stops invention. Together they make answers auditable.",
  l3: "Instruction pattern: answer only from the provided passages; cite document and section for each claim; if the passages don't answer, say so and suggest who to contact. Evaluate citation correctness separately from answer quality.",
  l4: "Citations can be wrong too (citing a real document for a claim it doesn't make). Spot-check citation faithfulness; consider quoting the exact sentence for high-stakes answers.",
  why: "It is how users and auditors trust document-based answers.", how: "Grounding instruction + per-claim citation + not-found behaviour + citation checks.",
  biz: "Reduces risk of wrong policy statements reaching employees or candidates.", analogy: "A footnoted report rather than an opinion.",
  ex: "'Per Travel Policy v4 §2.3, economy class applies to flights under 6 hours.'", hr: "'Relocation for UAE transfers is not covered in the documents I have. Please contact Global Mobility.'", gen: "Customer support citing the warranty clause.",
  mistakes: ["Trusting a citation without opening it", "No not-found rule"], risks: ["False confidence from wrong citations"],
  confused: [["C06.3", "C06.3 validates claims in content you publish; C11.4 builds citation into the assistant's answers."]],
  tools: ["NotebookLM", "Custom GPTs", "Claude Projects"], notWhen: [],
  exercise: "Write the grounding instruction for a policy assistant, including citation format and not-found wording.",
  predict: { q: "The assistant cites a real policy section, but that section doesn't say what the answer claims. What failed?", a: "Citation faithfulness: generation misrepresented the retrieved text. Spot-check citations and require quoting for high-stakes answers." } },
"C11.5": { l1: "Someone must own the knowledge base: update documents, remove old ones and control who sees what.", l2: "Owners, review dates, retirement rules and access rights for each document.", take: "Knowledge governance keeps the knowledge base current, owned and access-controlled.", aid: "Every document has an owner and an expiry.", hr: "Compensation guidelines restricted to comp team and TA leads.", mistake: "No review date." },
"C12.1": { l1: "Connect AI to several places at once: PDFs, spreadsheets, websites and dashboards.", l2: "Map which sources answer which kinds of question.", take: "Multi-source assistants read from several source types to answer one question.", aid: "Many sources, one answer.", hr: "Salary survey PDF + internal offers sheet + job-board data.", mistake: "Connecting everything without a source map." },
"C12.2": { l1: "Decide what questions the assistant answers and which sources it may use.", l2: "Write a source policy: allowed questions, permitted and excluded sources, ranking and recency window.", take: "Scope and source policy: allowed questions, permitted/excluded sources, ranking, recency.", aid: "Decide the library before the search.", hr: "Permitted: our offer data, licensed survey. Excluded: anonymous forum salary posts.", mistake: "Letting the open web outrank internal data." },
"C12.3": { l1: "When sources repeat or disagree, remove duplicates, put numbers in the same units and decide which source wins.", l2: "Normalise currency, dates and titles; prefer primary, recent and official sources; show the conflict when it can't be resolved.", take: "Deduplicate, normalise and resolve or disclose conflicts using explicit rules.", aid: "Same units, stated winner, visible conflict.", hr: "Survey says ₹14 LPA, internal offers say ₹12.5 LPA: different years and roles; normalise and explain.", mistake: "Averaging conflicting numbers silently." },
"C12.4": { l1: "Give one combined answer, with each claim showing its source.", l2: "Synthesis format: answer, supporting points with citations, conflicts, gaps.", take: "Cited synthesis: one answer, per-claim citations, conflicts and gaps shown.", aid: "One answer, many footnotes.", hr: "Campus compensation brief citing survey, internal data and two job boards.", mistake: "A blended answer with no traceability." },
"C12.5": { l1: "When the answer is spread across sources, check you have all the pieces and say when something is missing.", l2: "Coverage checks; 'partial answer' wording.", take: "Flag partial coverage when information is split and a source is missing.", aid: "Say what's missing.", hr: "'Bengaluru data available; Hyderabad survey not loaded.'", mistake: "Presenting a partial answer as complete." },
"C13.1": { l1: "A chatbot talks. An assistant helps with a role using context. An automation follows fixed steps. An agent works toward a goal and decides its own steps using tools. A multi-agent system is several agents with different jobs working together.",
  l2: "The differences are autonomy and action. Automations are predictable; agents are flexible but less predictable. Choose the least autonomous design that solves the problem.",
  l3: "Agent = model + instructions + tools + state/memory + a loop (observe → plan → act → check) + stop condition. Automation = fixed graph of steps. Assistant = model + role + context + memory, responding to the user. Multi-agent = several agents with defined roles and handoffs.",
  l4: "Agents add value when the steps vary by situation. They cost more (tokens, latency), are harder to test and need permissions and approvals. Current practice: start with workflows; use agents where flexibility clearly pays.",
  why: "Choosing the wrong pattern is the most expensive design mistake.", how: "Ask: are the steps fixed? Does it need to act in systems? Does it pursue a goal across steps?",
  biz: "Lets you explain to leaders why you didn't build an 'agent' when an automation was enough.", analogy: "Receptionist (chatbot), personal assistant (assistant), conveyor belt (automation), project manager (agent), project team (multi-agent).",
  ex: "Weekly report emailed every Monday = automation. Research a new market and draft a recommendation = agent or multi-agent.",
  hr: "Policy Q&A = assistant. Interview reminders = automation. Find slots across five calendars, handle conflicts, propose times = agent.",
  gen: "Invoice reminders = automation; procurement agent negotiating quotes within limits = agent.",
  mistakes: ["Calling every chatbot an agent", "Building an agent for fixed steps"], risks: ["Excessive autonomy without approval"],
  confused: [["C05.2", "Automations follow fixed blocks; agents choose their next step."]],
  tools: ["n8n", "Flowise", "Agent SDKs"], notWhen: ["Fixed, repeatable steps"],
  exercise: "Classify: (1) FAQ bot, (2) Monday pipeline email, (3) assistant that drafts intake briefs, (4) bot that sources candidates, messages them and books screens, (5) planner + researchers + writer producing a market report.",
  predict: { q: "A bot reads new CVs and moves strong ones to the next ATS stage. Which is it?", a: "If it applies fixed rules or one AI classification step, an automation. It becomes an agent only if it plans variable steps toward a goal. Either way it needs human review: it affects candidates." },
  allied: [{ t: "Workflows vs agents", s: "Anthropic's 'Building effective agents' (2024): workflows follow predefined paths; agents direct their own process. Start simple.", src: "EXT" }] },
"C13.2": { l1: "Split a big job into roles, like a team: one plans, one researches, one does the work, one checks it.",
  l2: "Each agent gets one clear responsibility, its own instructions and only the tools it needs. Clear roles make the system easier to test and fix.",
  l3: "Roles: Planner (breaks down the goal), Researcher (gathers evidence), Analyst (compares and finds patterns), Executor (takes actions), Writer (produces output), Reviewer/Validator (checks against sources and policy). Each has defined input, output and permissions.",
  l4: "More roles = more handoffs = more places to lose information and more cost. Merge roles that always run together; split only when instructions, tools or review independence differ.",
  why: "Clear roles are what make multi-agent systems controllable.", how: "List the work → group into responsibilities → one agent per responsibility → define inputs, outputs, tools.",
  biz: "Mirrors how consulting teams work, which makes it easy to explain to leaders.", analogy: "A newsroom: editor assigns, reporters research, writer drafts, sub-editor checks.",
  ex: "Market report: Planner → Researchers → Analyst → Writer → Reviewer.", hr: "Talent-market study: Planner sets sub-questions; Researchers gather job, salary and skills data; Analyst compares; Writer drafts; Reviewer checks claims against sources.", gen: "Competitor product launch analysis with the same roles.",
  mistakes: ["Two agents with overlapping jobs", "A Reviewer with no checklist"], risks: ["Unsupported claims slipping through handoffs"],
  confused: [["C13.4", "C13.2 defines who does what; C13.4 defines what they pass to each other."]],
  tools: ["n8n", "Flowise", "Agent frameworks"], notWhen: ["A single agent with a clear task works"],
  exercise: "Decompose 'Should we open a hiring hub in Coimbatore?' into roles with one responsibility each.",
  predict: { q: "What does a Reviewer agent catch that a Writer can't catch in itself?", a: "Independent verification: claims not supported by the Researchers' sources, policy breaches and tone issues, judged by separate instructions." },
  cvp: "The course teaches role decomposition. Current practice stresses using the fewest agents that work. Use the role vocabulary in the exam; apply the 'why not one agent?' test at work." },
"C13.3": { l1: "Agents can work one after another (sequential) or at the same time (parallel).", l2: "Sequential when each step needs the previous one; parallel when tasks are independent, followed by a merge step.", take: "Sequential for dependent steps; parallel for independent tasks with a merge.", aid: "Depends on it? Line up. Independent? Fan out.", hr: "Three Researchers in parallel (salary, skills, competitors) → Analyst merges.", mistake: "Parallel agents with no merge or dedup step." },
"C13.4": { l1: "When one agent hands work to the next, it should pass a clear, structured package, not a loose paragraph.",
  l2: "A handoff contract lists the fields passed, their format and what 'done' means. Shared context rules say what every agent sees and what stays private.",
  l3: "Handoff schema example: Researcher → Analyst: {claims:[{text, source_url, date, credibility}], gaps:[]}. Validate on receipt; reject incomplete handoffs. Shared context: goal, style guide, constraints. Private: tool credentials, raw scratch work.",
  l4: "Passing full transcripts wastes tokens and spreads errors; passing too little loses evidence. Structured schemas plus a summary field balance the two.",
  why: "Most multi-agent failures happen at the handoff.", how: "Define schema → validate → pass → log.",
  biz: "Makes multi-agent systems debuggable and auditable.", analogy: "A hospital shift handover using a standard form.",
  ex: "Planner → Researchers: {sub_question, sources_allowed, deadline}.", hr: "Analyst → Writer: {findings[], conflicts[], confidence} for the talent-market brief.", gen: "Order agent → billing agent: {order_id, items, amount, approvals}.",
  mistakes: ["Prose handoffs", "No validation"], risks: ["Information loss and unsupported claims"],
  confused: [["C03.5", "C03.5 structures one model's output; C13.4 applies that to agent-to-agent passing."]],
  tools: ["JSON schemas", "n8n", "Flowise"], notWhen: [],
  exercise: "Write the handoff schema from Researcher to Analyst for a competitor-hiring study.",
  predict: { q: "The final brief cites a salary figure no Researcher found. Where do you look first?", a: "The Writer's handoff input and the Reviewer's checks: the Writer added unsupported content and the Reviewer didn't verify claims against sources." } },
"C13.5": { l1: "MCP (Model Context Protocol) is a standard plug that lets AI connect to files, apps and data safely.", l2: "Instead of custom connections for every tool, MCP gives a common way to expose tools and data to AI, with scoped access.", take: "MCP is a standard protocol for connecting AI to tools and data with controlled access.", aid: "USB-C for AI tools.", hr: "An agent reads a shared requisition folder via MCP with read-only access.", mistake: "Granting write access 'for convenience'." },
"C13.6": { l1: "Limit what each agent can do, and require approval before it takes important actions.", l2: "Least privilege: read vs write tools; approvals before sending, deleting or updating records.", take: "Guardrails: least-privilege tool permissions and approval before consequential actions.", aid: "Read freely, write with permission.", hr: "Scheduling agent can read calendars; sending invites needs recruiter approval.", mistake: "Giving every agent every tool." },
"C13.7": { l1: "All agents should sound consistent and share the right memory.", l2: "Shared style guide and shared state; private scratch work.", take: "Consistent tone and shared memory rules across agents.", aid: "One voice, shared facts.", hr: "All candidate-facing outputs use the employer-brand voice guide.", mistake: "Each agent with its own tone." },
"C13.8": { l1: "When an agent system goes wrong, follow its steps one by one to find where it broke.", l2: "Trace inputs and outputs at every step and handoff; build regression tests from past failures.", take: "Debug agents by tracing each step and handoff; evaluate with test cases and metrics.", aid: "Follow the baton.", hr: "Trace shows the Researcher used an excluded source.", mistake: "Changing prompts without looking at the trace." },
"C14.1": { l1: "Responsible AI means AI that is fair, safe, transparent, private and has someone accountable for it.", l2: "Identify ethical risks early: who could be harmed, how, and what controls apply.", take: "Responsible AI principles: fairness, accountability, transparency, safety, privacy.", aid: "Who could be harmed, and who is accountable?", hr: "AI interview analysis could disadvantage non-native speakers.", mistake: "Treating ethics as a final checkbox." },
"C14.2": { l1: "AI can repeat unfair patterns from past data. Check for bias, protect privacy and get consent.", l2: "Watch for proxy variables (college, postcode, career gaps), test outcomes by group, and limit data to what's needed.", take: "Bias safeguards: check data, proxies and outcomes by group; protect privacy and consent.", aid: "Past patterns can be past prejudice.", hr: "Screening model trained on past hires favours a few colleges.", mistake: "Removing gender but keeping proxies for it." },
"C14.3": { l1: "Protect personal and confidential data when using AI.", l2: "Minimise data, use approved tools, control retention, know where data goes.", take: "Data protection: minimise, anonymise, approved tools, controlled retention.", aid: "Least data, approved place, limited time.", hr: "Candidate data only in the enterprise tenant.", mistake: "Using personal AI accounts for work data." },
"C14.4": { l1: "A person checks AI outputs at the right points before they cause harm.",
  l2: "Human-in-the-loop (HITL) means designed review points: who checks, what they check, and what authority they have to approve, edit or reject.",
  l3: "Patterns: approve-before-action (external messages, decisions), review-by-exception (low-confidence or flagged outputs), sampling audits (a share of low-risk outputs). Provide reviewers with the evidence and sources, not just the output.",
  l4: "Automation bias makes reviewers approve without reading; counter it with checklists, sampling of approved items and measuring edit rates. Too many review points erode ROI.",
  why: "It is the main control for medium- and high-risk AI uses.", how: "Identify harm points → choose review pattern → name reviewer → give evidence → log decision.",
  biz: "Lets organisations adopt AI in sensitive processes responsibly.", analogy: "A pilot with autopilot: the system flies, the pilot monitors and takes over at critical moments.",
  ex: "AI drafts customer refund responses; amounts above a threshold need a supervisor.",
  hr: "AI summarises candidate evidence; the hiring manager decides; rejections are reviewed by a recruiter.", gen: "AI flags suspicious invoices; finance analyst decides.",
  mistakes: ["Review steps with no checklist", "Reviewer lacks the source evidence"], risks: ["Rubber-stamping"],
  confused: [["C01.5", "C01.5 sets how much oversight; C14.4 designs the review."]],
  tools: ["Approval steps in n8n/Make", "Review queues"], notWhen: [],
  exercise: "Place human review points on a candidate follow-up automation and justify each.",
  predict: { q: "Recruiters approve 99% of AI-drafted rejection emails without edits. Good news?", a: "Maybe not: it may signal rubber-stamping. Sample approved emails, check quality and measure time spent reviewing." } },
"C14.5": { l1: "Before AI goes live, prove it works with tests, set up logging and monitoring, and know what to do when it fails.", l2: "Production readiness: test set and acceptance criteria, logging, monitoring, audit trail, incident response, owner.", take: "Production readiness: tested, logged, monitored, auditable, with an owner and incident plan.", aid: "Tested, tracked, owned.", hr: "Go-live checklist for the policy assistant.", mistake: "Pilot quietly becomes production without checks." },
"C15.1": { l1: "The capstone joins an assistant, a knowledge base and automations into one working solution.", l2: "Integrate pieces you built across the programme around one business problem.", take: "Integrated solution: assistant + knowledge base + automations in one workflow.", aid: "Join the pieces around one problem.", hr: "Recruitment operations assistant with policy RAG and status automations.", mistake: "Showing three disconnected demos." },
"C15.2": { l1: "Solve a complete, real business problem end to end.", l2: "Problem → design → build → test → measure.", take: "End-to-end problem solving from problem definition to measured result.", aid: "Real problem, real measure.", hr: "Reduce hiring-manager status queries by half.", mistake: "Choosing a problem with no measurable outcome." },
"C15.3": { l1: "Write guides so someone else can run and maintain your solution.", l2: "SOP: purpose, owners, steps, failure handling, contacts.", take: "Handover guides and SOPs make solutions sustainable.", aid: "If only you can run it, it isn't finished.", hr: "SOP for the TA ops team.", mistake: "No documentation." },
"C15.4": { l1: "Show the solution working and the difference it made.", l2: "Demo plus impact report: baseline, result, ROI, risks.", take: "Demo + impact report with before/after metrics.", aid: "Show it, prove it.", hr: "Five-minute demo with hours saved and query reduction.", mistake: "Demo without numbers." }
};

